#include "../src/FactoryRestore.hpp"
void factoryRackTests(){
    using M=Metropolix;using namespace metrobackup;
    rack::plugin::Plugin plugin;plugin.slug="MetropolixLab";modelMetropolix->plugin=&plugin;modelMetropolix->slug="Metropolix";plugin.models.push_back(modelMetropolix);rack::plugin::plugins.push_back(&plugin);
    auto m=std::unique_ptr<M>(new M);m->model=modelMetropolix;m->id=826;
    m->params[M::TEMPO].setValue(179.25f);m->params[M::RUN].setValue(1);m->params[M::RUN_ON_BOOT].setValue(1);m->params[M::INIT_PRESET].setValue(1);m->params[M::SCALE_LOCK].setValue(50);m->params[M::userScaleParam(0)].setValue(137);m->params[M::scaleShortcutParam(0)].setValue(51);
    m->params[M::PITCH].setValue(.2f);m->params[M::LOAD_PITCH].setValue(M::PitchThru);m->panelPickup[0].recall(.2f,.8f);m->expanded.store(true);m->modEditor.store(true);
    for(int slot=0;slot<64;++slot){auto s=m->capturePreset();s.values[M::PITCH]=slot/63.f;m->putPreset(slot,s);}
    M::ChainState chains;metro::ChainLink link;link.slot=63;link.repeats=3;link.mutes=5;chains.working.insert(0,link);for(int n=0;n<8;++n)chains.saved[n]=chains.working;chains.enabled=true;chains.loaded=2;m->setChainState(chains);
    m->uiPage.store(M::FACTORY_PAGE);m->setupCursor.store(M::SetupVersion);Json original(APP->engine->moduleToJson(m.get()));std::string error;
    for(int action=0;action<2;++action){
        APP->engine->moduleFromJson(m.get(),original.get());m->requestPreset(0);Json before,after;
        require(metrofactory::restore(m.get(),static_cast<metrofactory::Action>(action),before,after,error),"both maintenance actions apply");Json actual(APP->engine->moduleToJson(m.get()));auto* data=json_object_get(actual.get(),"data");auto* old=json_object_get(original.get(),"data");
        for(const char* key:{"midiInput","midiOutput","expanded","modEditor"})require(json_equal(json_object_get(data,key),json_object_get(old,key)),"maintenance preserves local devices and editor geometry");
        require(m->id==826 && m->integer(M::RUN)==0 && m->integer(M::RESET)==0 && !m->chainEnabled.load() && m->pendingSlot.load()==-1 && m->presetUiCommands.empty(),"maintenance stops transport, chain and pending loads without changing identity");
        for(const char* key:{"working","saved","loaded","follow","cursor"})require(json_equal(json_object_get(json_object_get(data,"chains"),key),json_object_get(json_object_get(old,"chains"),key)),"maintenance preserves working and eight saved chains");
        if(action==0){require(json_equal(json_object_get(data,"presets"),json_object_get(old,"presets")),"factory reset retains every saved musical snapshot");for(int id=0;id<M::NUM_PARAMS;++id)require(m->params[id].getValue()==m->paramQuantities[id]->defaultValue,"factory reset restores every plugin parameter default");require(!m->waitingPickup(M::PITCH) && m->uiPage.load()==M::FACTORY_PAGE && m->setupCursor.load()==M::SetupVersion,"factory reset clears pickup and returns to maintenance");}
        else{for(int slot=0;slot<64;++slot)require(!m->getPreset(slot).occupied,"clear presets erases every bank slot");auto* params=json_object_get(actual.get(),"params");for(int id=0;id<M::NUM_PARAMS;++id)if(id!=M::RUN && id!=M::RESET)require(json_equal(json_array_get(params,id),json_array_get(json_object_get(original.get(),"params"),id)),"clear presets retains every live non-transport setting");require(json_equal(json_object_get(data,"pickup"),json_object_get(old,"pickup")),"clear presets retains physical and sounding pickup state");}
        APP->engine->moduleFromJson(m.get(),before.get());Json undo(APP->engine->moduleToJson(m.get()));require(json_equal(undo.get(),original.get()),"maintenance receipt restores exact previous running bank and settings");APP->engine->moduleFromJson(m.get(),after.get());Json redo(APP->engine->moduleToJson(m.get()));require(json_equal(redo.get(),actual.get()),"maintenance redo restores exact stopped result");
        Json settings(capture(actual.get(),All));Scope scope=All;require(validate(m.get(),settings.get(),scope,error),"post-maintenance full backup validates");
    }
    {Json before(APP->engine->moduleToJson(m.get())),old,next;require(!metrofactory::restore(m.get(),static_cast<metrofactory::Action>(3),old,next,error),"unknown maintenance action rejects");Json after(APP->engine->moduleToJson(m.get()));require(json_equal(before.get(),after.get()),"invalid maintenance action has no effect");}
    m->putPreset(0,m->capturePreset());m->requestPreset(0);require(!m->presetUiCommands.empty(),"pending preset fixture actually has a queued command");{Json before,after;require(metrofactory::restore(m.get(),metrofactory::ResetSettings,before,after,error) && m->presetUiCommands.empty() && m->pendingSlot.load()==-1,"factory reset cancels pending loads while preserving saved presets");}
    m->uiPage.store(M::FACTORY_CONFIRM_PAGE);m->factoryConfirmCursor=1;Json disarmed(m->dataToJson());require(json_integer_value(json_object_get(disarmed.get(),"uiPage"))==M::FACTORY_PAGE && !json_object_get(disarmed.get(),"factoryConfirmCursor"),"save never arms maintenance confirmation");json_object_set_new(disarmed.get(),"uiPage",json_integer(M::FACTORY_CONFIRM_PAGE));m->dataFromJson(disarmed.get());require(m->uiPage.load()==M::FACTORY_PAGE && m->factoryConfirmCursor==0,"patch import and undo cannot reopen armed confirmation");
    APP->engine->moduleFromJson(m.get(),original.get());m->params[M::RESET_INPUT_MODE].setValue(1);m->inputs[M::RESET_IN].channels=1;m->inputs[M::RESET_IN].setVoltage(5);Module::ProcessArgs args{};args.sampleRate=48000;args.sampleTime=1.f/48000;for(int n=0;n<64;++n)m->process(args);Json before,after;require(metrofactory::restore(m.get(),metrofactory::ClearPresets,before,after,error),"clear works under held external Run");for(int n=0;n<64;++n)m->process(args);require(!m->sequencer.running,"maintenance cannot restart under already high Run gate");
    rack::plugin::plugins.pop_back();plugin.models.clear();modelMetropolix->plugin=nullptr;std::cout<<"PASS: factory settings reset, all-preset clear, preserved banks/devices, exact receipts and disarmed confirmation\n";
}
